// Garante que a saída de texto do Agente seja um JSON válido e parseável,
// mesmo que venha com blocos ```json, crases ou texto extra ao redor.
// Toda a extração/validação do schema é feita aqui, sem depender de um
// node de Output Parser.
const item = $input.first().json;

function normalizarCriterios(lista) {
  if (!Array.isArray(lista)) return [];
  return lista
    .filter(c => c && typeof c === 'object')
    .map(c => ({
      criterio: typeof c.criterio === 'string' ? c.criterio : '',
      atendido: c.atendido === true
    }))
    .filter(c => c.criterio);
}

function montarResultado(parsed) {
  return {
    cliente_nome: parsed.cliente_nome ?? '',
    descricao_problema: parsed.descricao_problema ?? '',
    exemplo_pedido: parsed.exemplo_pedido ?? '',
    testes_realizados: parsed.testes_realizados ?? '',
    tema: parsed.tema ?? '',
    criterios_tema: normalizarCriterios(parsed.criterios_tema)
  };
}

let raw = item.output ?? item.text ?? item.content ?? '';

// Caso alguma variação do node já devolva um objeto estruturado, usa direto
if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
  return [{ json: montarResultado(raw) }];
}

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw);
}

// Remove blocos de código markdown e crases soltas
let cleaned = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/`/g, '')
  .trim();

// Isola apenas o objeto JSON mais externo, caso haja texto ao redor
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  cleaned = cleaned.substring(firstBrace, lastBrace + 1);
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  parsed = {
    cliente_nome: '',
    descricao_problema: '',
    exemplo_pedido: '',
    testes_realizados: '',
    tema: '',
    criterios_tema: [],
    erro: 'Não foi possível interpretar a resposta da IA como JSON.',
    resposta_bruta: raw
  };
  return [{ json: parsed }];
}

return [{ json: montarResultado(parsed) }];
